/* cppi::c4ce6a5881e0c9f800acf6a9f7dc6f7433d8789854c72f1c51c9ad60bce8222e */
SELECT COUNT(*) FROM (SELECT pnl.business_date, ref.abor_instrument_type_id, ref.abor_security_group_name, ref.abor_security_type_name, sum(market_value_reporting_currency) AS mv_rc, sum(period_result_node_by_node_reporting_currency) AS pnl_rc FROM performance.scd_performance_seclvl pnl LEFT JOIN reference.scd_securities ref ON pnl.aggregation_level_3 = ref.abor_security_id AND ref.business_date = (SELECT max(business_date) FROM reference.scd_securities) WHERE pnl.business_date BETWEEN '2024-04-01' AND '2025-03-31' AND aggregation_level_1 IN (SELECT model_portfolio FROM performance.scd_performance_invstr_flatten pif WHERE pif.business_date = (SELECT max(business_date) FROM performance.scd_performance_invstr_flatten) AND investmentstructurelevel3 IN ('EPM', 'Macro Strategies', 'Quantitative Strategies & Risk Premia') AND investmentstructurelevel4 IN ('EPM Core', 'EPM Corporate Expenses', 'EPM Legacy', 'MS CMF Common', 'Legacy')) GROUP BY pnl.business_date, ref.abor_instrument_type_id, ref.abor_security_group_name, ref.abor_security_type_name
) dbvrcnt

/* cppi::c4ce6a5881e0c9f800acf6a9f7dc6f7433d8789854c72f1c51c9ad60bce8222e */
SELECT COUNT(*) FROM (SELECT pnl.business_date, ref.abor_instrument_type_id, ref.abor_security_group_name, ref.abor_security_type_name, sum(market_value_reporting_currency) AS mv_rc, sum(period_result_node_by_node_reporting_currency) AS pnl_rc FROM performance.scd_performance_seclvl pnl LEFT JOIN reference.scd_securities ref ON pnl.aggregation_level_3 = ref.abor_security_id AND ref.business_date = (SELECT max(business_date) FROM reference.scd_securities) WHERE pnl.business_date BETWEEN '2024-04-01' AND '2025-03-31' AND aggregation_level_1 IN (SELECT model_portfolio FROM performance.scd_performance_invstr_flatten pif WHERE pif.business_date = (SELECT max(business_date) FROM performance.scd_performance_invstr_flatten) AND investmentstructurelevel3 IN ('EPM', 'Macro Strategies', 'Quantitative Strategies & Risk Premia') AND investmentstructurelevel4 IN ('EPM Core', 'EPM Corporate Expenses', 'EPM Legacy', 'MS CMF Common', 'Legacy')) GROUP BY pnl.business_date, ref.abor_instrument_type_id, ref.abor_security_group_name, ref.abor_security_type_name
) dbvrcnt

/* cppi::c4ce6a5881e0c9f800acf6a9f7dc6f7433d8789854c72f1c51c9ad60bce8222e */
SELECT COUNT(*) FROM (SELECT pnl.business_date, ref.abor_instrument_type_id, ref.abor_security_group_name, ref.abor_security_type_name, sum(market_value_reporting_currency) AS mv_rc, sum(period_result_node_by_node_reporting_currency) AS pnl_rc FROM performance.scd_performance_seclvl pnl LEFT JOIN reference.scd_securities ref ON pnl.aggregation_level_3 = ref.abor_security_id AND ref.business_date = (SELECT max(business_date) FROM reference.scd_securities) WHERE pnl.business_date BETWEEN '2024-04-01' AND '2025-03-31' AND aggregation_level_1 IN (SELECT model_portfolio FROM performance.scd_performance_invstr_flatten pif WHERE pif.business_date = (SELECT max(business_date) FROM performance.scd_performance_invstr_flatten) AND investmentstructurelevel3 IN ('EPM', 'Macro Strategies', 'Quantitative Strategies & Risk Premia') AND investmentstructurelevel4 IN ('EPM Core', 'EPM Corporate Expenses', 'EPM Legacy', 'MS CMF Common', 'Legacy')) GROUP BY pnl.business_date, ref.abor_instrument_type_id, ref.abor_security_group_name, ref.abor_security_type_name
) dbvrcnt

